using Microsoft.EntityFrameworkCore;using ProMaxx2.QA.Application.Requirements;using ProMaxx2.QA.Domain.Requirements;using ProMaxx2.QA.Application.Common;
namespace ProMaxx2.QA.Infrastructure.Persistence;
public sealed class RequirementRepository(QaDbContext db,ProjectAccessContext projectCtx):IRequirementRepository
{
 private static RequirementDto Map(Requirement x,int testCaseCount)=>new(x.RequirementId,x.ProjectId,x.ReleaseId,x.ModuleId,x.RequirementCode,x.Title,x.Description,x.AcceptanceCriteria,x.Priority,x.RiskLevel,x.Source,x.OwnerUserId,x.Status,x.RevisionNo,x.IsInScope,x.CreatedAt,testCaseCount);
 public async Task<PagedResult<RequirementDto>>ListAsync(RequirementFilter f,CancellationToken ct){var q=db.Requirements.AsNoTracking().Where(x=>!x.IsDeleted);if(f.ProjectId.HasValue)q=q.Where(x=>x.ProjectId==f.ProjectId);else if(projectCtx.AllowedProjectIds.Length>0)q=q.Where(x=>projectCtx.AllowedProjectIds.Contains(x.ProjectId));else q=q.Where(_=>false);if(f.ReleaseId.HasValue)q=q.Where(x=>x.ReleaseId==f.ReleaseId);if(f.ModuleId.HasValue)q=q.Where(x=>x.ModuleId==f.ModuleId);if(!string.IsNullOrWhiteSpace(f.Status))q=q.Where(x=>x.Status==f.Status);if(!string.IsNullOrWhiteSpace(f.Priority))q=q.Where(x=>x.Priority==f.Priority);if(f.InScope.HasValue)q=q.Where(x=>x.IsInScope==f.InScope);if(!string.IsNullOrWhiteSpace(f.Search))q=q.Where(x=>x.RequirementCode.Contains(f.Search)||x.Title.Contains(f.Search));var total=await q.CountAsync(ct);var p=Math.Max(1,f.Page);var s=Math.Clamp(f.Size,20,100);var items=await q.OrderBy(x=>x.RequirementCode).Skip((p-1)*s).Take(s).ToListAsync(ct);var reqIds=items.Select(x=>x.RequirementId).ToList();var caseCounts=await db.RequirementTestCases.AsNoTracking().Where(x=>reqIds.Contains(x.RequirementId)).GroupBy(x=>x.RequirementId).ToDictionaryAsync(g=>g.Key,g=>g.Count(),ct);return new(total,items.Select(x=>Map(x,caseCounts.GetValueOrDefault(x.RequirementId,0))).ToList());}
 public async Task<RequirementDto?>GetAsync(Guid id,CancellationToken ct){var allowed=projectCtx.AllowedProjectIds;var x=await db.Requirements.AsNoTracking().SingleOrDefaultAsync(x=>x.RequirementId==id&&!x.IsDeleted,ct);if(x is null||(allowed.Length>0&&!allowed.Contains(x.ProjectId)))return null;var tc=await db.RequirementTestCases.AsNoTracking().CountAsync(r=>r.RequirementId==id,ct);return Map(x,tc);}public async Task<Requirement?>FindAsync(Guid id,CancellationToken ct){var allowed=projectCtx.AllowedProjectIds;var x=await db.Requirements.SingleOrDefaultAsync(x=>x.RequirementId==id&&!x.IsDeleted,ct);if(x is not null&&allowed.Length>0&&!allowed.Contains(x.ProjectId))return null;return x;}public Task<bool>CodeExistsAsync(Guid projectId,string code,CancellationToken ct)=>db.Requirements.AnyAsync(x=>x.ProjectId==projectId&&x.RequirementCode==code,ct);public async Task<IReadOnlyList<string>>ListCodesAsync(Guid projectId,string prefix,CancellationToken ct)=>await db.Requirements.AsNoTracking().Where(x=>x.ProjectId==projectId&&x.RequirementCode.StartsWith(prefix)).Select(x=>x.RequirementCode).ToListAsync(ct);public Task AddAsync(Requirement e,CancellationToken ct)=>db.Requirements.AddAsync(e,ct).AsTask();public void AddRevision(RequirementRevision revision)=>db.RequirementRevisions.Add(revision);public async Task<IReadOnlyList<RequirementRevisionDto>>RevisionsAsync(Guid id,CancellationToken ct)=>await db.RequirementRevisions.AsNoTracking().Where(x=>x.RequirementId==id).OrderByDescending(x=>x.RevisionNo).Select(x=>new RequirementRevisionDto(x.RevisionNo,x.Title,x.Description,x.AcceptanceCriteria,x.ChangedBy,x.ChangedAt,x.ChangeReason)).ToListAsync(ct);public Task SaveAsync(CancellationToken ct)=>db.SaveChangesAsync(ct);
}
